solutions.naive:
class Solution:
    def maximumScore(self, nums: list[int], k: int) -> int:
        best=0
        for l in range(k+1):
            for r in range(k,len(nums)):
                mn=nums[l]
                for i in range(l,r+1): mn=min(mn,nums[i])
                best=max(best,mn*(r-l+1))
        return best

